import json
for f in ['outputs/phase2_scierc_semantic_only.jsonl', 'outputs/phase2_scierc_full_s1.jsonl']:
    lines = open(f).readlines()
    good = []
    bad = []
    for i, l in enumerate(lines):
        try:
            json.loads(l)
            good.append(l)
        except:
            bad.append((i, l[:80]))
    with open(f, 'w') as out:
        for g in good:
            out.write(g)
    print(f + ': kept ' + str(len(good)) + ' lines, removed ' + str(len(bad)) + ' bad lines')
    for b in bad:
        print('  removed line ' + str(b[0]) + ': ' + repr(b[1]))
"
